CREATE TABLE IF NOT EXISTS transaction_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid NOT NULL REFERENCES capital_opportunities(id) ON DELETE CASCADE, institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, interest_type text NOT NULL DEFAULT 'information', amount numeric(20,2), currency text NOT NULL DEFAULT 'NGN', message text, status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());